/** One coin's forced-liquidation cascade state over the trailing window. */
export const SqueezeAlert = z.looseObject({
  symbol: z.string(),
  /** short_squeeze | long_flush | balanced. Named after the side being LIQUIDATED: a short liquidation is forced buying, so short_squeeze is upward pressure */
  direction: z.string(),
  /** 0..1 composite of spike_ratio, asymmetry and notional. Ratios carry 80% of the weight because absolute notionals run low (Binance excluded) */
  severity: z.number(),
  /** True when every gate clears: spike_ratio, asymmetry, severity, a minimum absolute notional and a minimum baseline age — i.e. a cascade is firing, not just churn */
  triggered: z.boolean(),
  /** Which gates blocked the alert, empty when triggered. One or more of: no_spike_baseline, spike_ratio, asymmetry, severity, min_notional (window below the absolute floor — the ratios alone must not be able to raise an a... */
  suppressed_by: z.array(z.string()).nullish(),
  /** Trailing window the figures cover, in seconds */
  window_s: z.number().nullish(),
  long_liq_usd: z.number(),
  short_liq_usd: z.number(),
  total_liq_usd: z.number(),
  /** Dominant side's share of window notional: 0.5 = two-sided churn, 1.0 = entirely one-sided */
  asymmetry: z.number(),
  /** Dominant side divided by the opposing side (the '334x' figure). null when the opposing side is exactly zero */
  side_ratio: z.number().nullish(),
  /** Window liquidation total vs this coin's own trailing-24h mean over an equal window. ~1 is normal; >= 2 is required to trigger */
  spike_ratio: z.number().nullish(),
  liq_24h_usd: z.number().nullish(),
  /** Open-interest change over the same window. null until the OI history has two samples */
  oi_change_pct: z.number().nullish(),
  /** covering | fresh_longs | capitulating | fresh_shorts | unclear. Reads oi_change_pct against `direction`: OI falling into a short squeeze means shorts are being closed out; OI rising means the move is being fed. null w... */
  oi_state: z.string().nullish(),
  /** Context only — 24h mark vs prevDayPx. Direction is derived from liquidation flow, not from this */
  price_change_24h_pct: z.number().nullish(),
  /** The three severity components before weighting */
  legs: z.record(z.string(), z.number()).nullish(),
  /** Which venue feeds the totals aggregate */
  coverage: z.string().nullish(),
  /** Hours the liquidation FEED PROCESS has been connected. Not the same as baseline_span_h — the feed restores up to 24h of events from its snapshot on boot, so this resets on every deploy while the history does not */
  window_uptime_h: z.number().nullish(),
  /** Hours of history actually behind spike_ratio. This is the number to check before trusting a spike; triggering is gated on it, not on window_uptime_h */
  baseline_span_h: z.number().nullish(),
});
export type SqueezeAlert = z.infer<typeof SqueezeAlert>;

/** Coins whose forced-liquidation flow is currently one-sided and abnormal. */
export const SqueezeAlertsResponse = z.looseObject({
  as_of: z.number(),
  window_s: z.number(),
  min_severity: z.number(),
  count: z.number(),
  /** Coins that had a usable liquidation window. `count` of these cleared the thresholds */
  evaluated: z.number(),
  coverage: z.string().nullish(),
  alerts: z.array(SqueezeAlert),
});
export type SqueezeAlertsResponse = z.infer<typeof SqueezeAlertsResponse>;

